using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;public static class TownPanBoundsQA{public static object Main(){if(!EditorApplication.isPlaying)throw new Exception("Play mode required");var cam=Camera.main;var target=GameObject.Find("Hometown/Town Camera Pan Target").transform;var box=GameObject.Find("Hometown/Town Camera Land Bounds").GetComponent<BoxCollider2D>();var aspectBox=cam.GetComponent<TimelessEchoes.AspectRatioBox>();var oldPos=target.position;var oldRT=cam.targetTexture;var oldRect=cam.rect;bool oldEnabled=aspectBox.enabled;var rt=new RenderTexture(1024,576,24);int index=0;double next=0;bool prepared=false;var rows=new List<string>();EditorApplication.CallbackFunction tick=null;Action clean=()=>{EditorApplication.update-=tick;cam.targetTexture=oldRT;cam.rect=oldRect;cam.ResetAspect();aspectBox.enabled=oldEnabled;target.position=oldPos;rt.Release();UnityEngine.Object.DestroyImmediate(rt);};tick=()=>{try{if(EditorApplication.timeSinceStartup<next)return;if(index>=8){File.WriteAllLines("output/scene-review/town-pan-bounds-qa.txt",rows);clean();return;}if(!prepared){aspectBox.enabled=false;cam.rect=new Rect(0,0,1,1);rt.Release();rt.width=index<4?1024:2048;rt.height=576;rt.Create();cam.targetTexture=rt;cam.aspect=rt.width/(float)rt.height;target.position=new Vector3(index%2==0?-1000:1000,index%4<2?-1000:1000,0);prepared=true;next=EditorApplication.timeSinceStartup+1;return;}var lo=cam.ViewportToWorldPoint(new Vector3(0,0,10));var hi=cam.ViewportToWorldPoint(new Vector3(1,1,10));var b=box.bounds;bool pass=lo.x>=b.min.x-.01f&&lo.y>=b.min.y-.01f&&hi.x<=b.max.x+.01f&&hi.y<=b.max.y+.01f;rows.Add($"case={index} aspect={cam.aspect} size={cam.orthographicSize} view=({lo.x},{lo.y})..({hi.x},{hi.y}) PASS={pass}");if(!pass)throw new Exception(rows[rows.Count-1]);cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();File.WriteAllBytes($"output/scene-review/town-pan-corner-{index}.png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);RenderTexture.active=old;index++;prepared=false;}catch(Exception e){rows.Add("FAIL "+e);File.WriteAllLines("output/scene-review/town-pan-bounds-qa.txt",rows);clean();}};EditorApplication.update+=tick;return "Eight rendered corner checks scheduled; original camera state restored afterward";}}
